from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
import json
import os
import copy

app = FastAPI()

# Global configuration store - used by all request handlers
_config = {
    "app": {
        "name": "inventory-service",
        "version": "2.1.0",
        "debug": False
    },
    "paths": {
        "data_dir": "/app/data",
        "cache_dir": "/app/cache",
        "log_dir": "/app/logs"
    },
    "features": {
        "audit_logging": True,
        "rate_limiting": True
    }
}

def deep_merge(base: dict, override: dict) -> dict:
    """Recursively merge override into base dict.
    Used for tenant-specific configuration overlays.
    """
    result = copy.deepcopy(base)
    for key, value in override.items():
        if key == "__proto__" or key == "__class__":
            # Basic prototype pollution guard for common patterns
            continue
        if isinstance(value, dict) and key in result and isinstance(result[key], dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result


@app.post("/api/v1/config/overlay")
async def apply_config_overlay(request: Request):
    """Apply tenant configuration overlay to global config.
    Accepts nested JSON that gets merged into running config.
    """
    global _config
    try:
        body = await request.json()
        if not isinstance(body, dict):
            return JSONResponse({"error": "Expected JSON object"}, status_code=400)
        _config = deep_merge(_config, body)
        return JSONResponse({"status": "ok", "config": _config})
    except json.JSONDecodeError:
        return JSONResponse({"error": "Invalid JSON"}, status_code=400)


@app.get("/api/v1/export")
async def export_data():
    """Export data from configured data directory."""
    data_dir = _config["paths"]["data_dir"]
    try:
        files = os.listdir(data_dir)
        results = {}
        for f in files:
            filepath = os.path.join(data_dir, f)
            if os.path.isfile(filepath):
                with open(filepath, 'r') as fh:
                    results[f] = fh.read()
        return JSONResponse({"data": results})
    except PermissionError as e:
        return JSONResponse({"error": f"Access denied: {e}"}, status_code=403)
    except FileNotFoundError:
        return JSONResponse({"error": f"Directory not found: {data_dir}"}, status_code=404)


@app.get("/api/v1/logs")
async def read_logs():
    """Read application logs from configured log directory."""
    log_dir = _config["paths"]["log_dir"]
    try:
        log_file = os.path.join(log_dir, "app.log")
        if os.path.exists(log_file):
            with open(log_file, 'r') as f:
                return JSONResponse({"logs": f.readlines()[-100:]})
        return JSONResponse({"logs": []})
    except PermissionError as e:
        return JSONResponse({"error": f"Access denied: {e}"}, status_code=403)


@app.get("/api/v1/health")
async def health():
    return JSONResponse({"status": "healthy", "config": _config["app"]})
